/* Gate 2 唯一正式流程：/gate-2/ 只載入此檔，避免舊測試畫面覆寫新場景。 */
const G2_KEY='rules-city-gate2-v4';
const G2_BILLS={blue:{tag:'政府案',name:'《校園安全管理法部分條文修正草案》',by:'提案機關：行政院'},orange:{tag:'委員案',name:'《校園安全管理法第十二條、第十五條及第十八條條文修正草案》',by:'提案人：陳○○等｜連署：17人'}};
const G2_DOCS={
 agenda:{title:'議事日程審定紀錄',body:'兩份法律案已排入院會議程。'},
 direct:{title:'逕付二讀紀錄',body:'提議完成；20人以上連署或附議後，經院會表決通過。應交付黨團協商。'},
 report:{title:'委員會審查報告',body:'審查結果：審查完竣。部分條文仍有爭議。本案決議交付黨團協商。'},
 negotiation:{title:'黨團協商結論',body:'本案部分條文依協商內容修正；代表簽署確認結論。'},
 second:{title:'第二讀會程序紀錄',body:'本案依序完成廣泛討論、逐條討論與條文議決。'},
 third:{title:'第三讀會議決紀錄',body:'文字修正確認後，全案表決三讀通過。'},
 promulgation:{title:'公布紀錄',body:'立法院咨請總統公布。公布日期：10月12日。'}
};
const G2_INIT=()=>({stage:'intro',intro:false,viewed:[],selected:null,agenda:[],branch:{},sign:18,review:[],folder:[],checked:[],negSlots:[null,null,null],negStamped:false,order:[null,null,null],third:0,falseFinish:false,promulgated:false,effective:false,verify:[null,null,null],done:false});
let g2=G2_INIT();
const g2App=document.querySelector('#app');
function g2Save(){localStorage.setItem(G2_KEY,JSON.stringify(g2))}
function g2Load(){try{let x=JSON.parse(localStorage.getItem(G2_KEY));if(x&&x.stage)g2={...G2_INIT(),...x}}catch(e){}}
function g2Esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function g2AddDoc(id){if(!g2.folder.includes(id))g2.folder.push(id);g2Save()}
function g2CheckDoc(id){if(!g2.checked.includes(id))g2.checked.push(id);g2Save()}
function g2Hud(){return `<header class="g2-hud"><div><b>貳｜尚未完成的法案</b><small>立法程序紀錄</small></div><button class="g2-folder" data-action="folder">▰<span>文件夾</span></button></header>`}
function g2Scene(place,content){g2App.innerHTML=`<section class="g2-game g2-${place}">${g2Hud()}<div class="g2-place-name">${place==='committee'?'委員會會議室':place==='negotiation'?'黨團協商會議室':'立法院議場'}</div><main class="g2-stage">${content}</main><p class="g2-message" id="g2-message"></p></section>`;if(place==='negotiation'){let board=document.querySelector('.g2-clipboard');if(board)board.style.backgroundImage="linear-gradient(#5a3e2c,#8a684c),var(--g2-evidence-board)"}g2Bind()}
function g2Message(text){let p=document.querySelector('#g2-message');if(p)p.textContent=text}
function g2Modal(html){let e=document.createElement('section');e.className='g2-modal';e.innerHTML=`<div class="g2-modal-paper"><button class="g2-close" data-action="close">×</button>${html}</div>`;g2App.append(e);g2Bind()}
function g2Folder(){g2Modal(`<h2>文件夾</h2><p class="g2-folder-intro">這些文件是你修復程序紀錄時留下的證據。</p>${g2.folder.length?g2.folder.map(id=>`<button class="g2-folder-row" data-action="doc" data-docid="${id}">${g2Esc(G2_DOCS[id].title)}${g2.checked.includes(id)?'<i>已核對</i>':''}</button>`).join(''):'<p>目前還沒有程序文件。</p>'}`)}
function g2ShowDoc(id){let d=G2_DOCS[id];g2Modal(`<article class="g2-document-view"><em>程序文件</em><h2>${g2Esc(d.title)}</h2><p>${g2Esc(d.body)}</p>${g2.checked.includes(id)?'<i class="checked-stamp">已核對</i>':''}</article>`)}
function g2Bill(id,cls=''){let b=G2_BILLS[id];return `<button class="g2-bill ${id} ${cls}" data-item="bill:${id}"><small>${b.tag}</small><b>${b.name}</b><span>${b.by}</span></button>`}
function g2Paper(id,kind='neg'){let d=G2_DOCS[id]||{title:id,body:''};return `<button class="g2-paper ${kind}" data-item="${kind}:${id}"><b>${d.title}</b><small>${d.body}</small></button>`}
function g2Start(){g2Load();g2Render()}
function g2Render(){({intro,agenda,first,branch,direct,directexit,committee,committeeexit,negotiation,second,third,falsefinish,promulgation,effective,verify,complete}[g2.stage]||intro)()}
function intro(){g2Scene('chamber panorama',`<div class="g2-explore-pan" id="g2-explore-pan"><div class="g2-explore-world"><div class="g2-intro-docs ${g2.intro?'show':''}"><button class="g2-scene-file blue" data-action="viewbill" data-bill="blue"><small>政府案</small>查看行政院案</button><button class="g2-scene-file orange" data-action="viewbill" data-bill="orange"><small>委員案</small>查看委員案</button>${g2.viewed.length===2?'<button class="g2-begin-procedure" data-action="to-agenda">前往議事程序桌</button>':''}</div></div></div><div class="g2-arrival"><b>貳｜尚未完成的法案</b><span>兩份尚未完成的立法紀錄，散落在這裡。</span></div><div class="g2-intro-dialogue ${g2.intro?'hidden':''}"><p>本屆立法委員任期即將屆滿。</p><p>但還有兩份修法紀錄，沒有走完。</p><p>在時間結束以前，把它們送回正確的程序。</p><button data-action="intro">開始追蹤</button></div><div class="g2-swipe-cue ${g2.intro?'show':''}">左右滑動查看議場</div>`)}
function g2ViewBill(id){if(!g2.viewed.includes(id)){g2.viewed.push(id);g2Save()}let b=G2_BILLS[id];g2Modal(`<article class="g2-document-view bill-view ${id}"><em>${b.tag==='政府案'?'法律案':'委員提案'}</em><h2>${b.name}</h2><p>${b.by}</p><div class="g2-lines"></div><small>查看後，文件仍會放回議事桌。</small></article>`)}
function agenda(){let queued=id=>g2.agenda.includes(id);g2Scene('chamber',`<p class="g2-prompt">法律案已經提出。下一站是哪裡？</p><div class="g2-agenda-table"><div class="g2-agenda-book"><em>議事日程</em><b>程序委員會紀錄</b><small>待排入院會議程的法律案</small></div><div class="g2-trays"><button class="g2-tray procedure" data-drop="agenda:procedure"><b>程序委員會</b><small>議事日程</small><span>${g2.agenda.map(id=>'<i>文件</i>').join('')||'文件盤'}</span></button><button class="g2-tray" data-drop="agenda:committee"><b>委員會審查</b><small>審查法案</small></button><button class="g2-tray" data-drop="agenda:second"><b>第二讀會</b><small>院會程序</small></button></div></div><div class="g2-bill-pair">${queued('blue')?'':g2Bill('blue')}${queued('orange')?'':g2Bill('orange')}</div>`)}
function first(){g2Scene('chamber',`<article class="g2-record"><em>第一讀會</em><h2>主席台前的程序紀錄</h2><p>選擇此刻應進行的動作。</p></article><div class="g2-slip-row">${['朗讀議案標題','逐條討論','全案表決'].map(x=>`<button data-action="first" data-value="${x}">${x}</button>`).join('')}</div>`)}
function branch(){g2Scene('chamber',`<article class="g2-record compact"><p>行政院案：交付委員會審查</p><p>委員案：有人提議逕付二讀</p></article><div class="g2-bill-pair">${g2.branch.blue?'':g2Bill('blue')}${g2.branch.orange?'':g2Bill('orange')}</div><div class="g2-tray-pair"><button class="g2-tray" data-drop="branch:committee"><b>委員會審查</b></button><button class="g2-tray" data-drop="branch:direct"><b>逕付二讀</b></button></div>`)}
function direct(){let names=['林委員','許委員','周委員','方委員','吳委員'];g2Scene('chamber',`<article class="g2-record signature"><em>逕付二讀程序紀錄</em><p>提議 ✓</p><p>連署／附議：<b>${g2.sign} / 20</b></p></article><div class="g2-name-row">${names.map((n,i)=>g2.sign>18+i?'':`<button data-item="sign:${i}">${n}</button>`).join('')}</div><button class="g2-sign-book" data-drop="direct:sign">連署名冊</button><button class="g2-vote" data-action="vote" ${g2.sign<20?'disabled':''}>院會表決</button>`)}
function directexit(){g2Scene('chamber',`<article class="g2-record compact"><em>逕付二讀</em><p>院會表決通過。這份案子的程序還沒有結束。</p></article>${g2Bill('orange')}<div class="g2-tray-pair"><button class="g2-tray" data-drop="directexit:second"><b>第二讀會</b></button><button class="g2-tray" data-drop="directexit:negotiation"><b>黨團協商</b></button></div>`)}
function committee(){let pieces=['修正意見','保留意見','審查資料'];g2Scene('committee',`<p class="g2-prompt">把審查資料整理回報告夾。</p><div class="g2-review-table"><button class="g2-review-folder" data-drop="review:folder"><b>委員會審查資料夾</b><small>整理中的審查文件</small></button><div class="g2-review-papers">${pieces.filter(x=>!g2.review.includes(x)).map(x=>`<button data-item="review:${x}">${x}</button>`).join('')}</div></div>`)}
function committeeexit(){g2Scene('committee',`<article class="g2-report"><em>委員會審查報告</em><p>審查結果：審查完竣</p><p>部分條文仍有爭議。本案決議交付黨團協商。</p></article>${g2Bill('blue')}<div class="g2-tray-pair"><button class="g2-tray" data-drop="committeeexit:second"><b>第二讀會</b></button><button class="g2-tray" data-drop="committeeexit:negotiation"><b>黨團協商</b></button></div>`)}
const NEG={head:{title:'黨團協商結論',body:'本案修正協商文件'},body:{title:'協商紀錄',body:'本案部分條文依協商內容修正……'},sign:{title:'協商結論',body:'各代表簽署欄與確認結論'},report:{title:'委員會審查報告',body:'審查完竣・前一階段文件'},second:{title:'第二讀會逐條討論紀錄',body:'尚未進入第二讀會'}};
function negPaper(id){let d=NEG[id];return `<button class="g2-paper neg ${id}" data-item="neg:${id}"><b>${d.title}</b><small>${d.body}</small></button>`}
function negotiation(){let slots=g2.negSlots,ready=slots.every(Boolean)&&!g2.negStamped;let all=Object.keys(NEG).filter(id=>!slots.includes(id));g2Scene('negotiation',`<p class="g2-prompt">從散落的文件中，修復一份完整的協商結論。</p><div class="g2-neg-desk"><div class="g2-clipboard"><div class="g2-clip-title">黨團協商結論</div>${[0,1,2].map(i=>`<div class="g2-neg-slot" style="top:${[17,42,67][i]}%;height:22%" data-drop="neg:${i}"><i>${['①','②','③'][i]}</i>${slots[i]?negPaper(slots[i]):''}</div>`).join('')}<div class="g2-stamp-area" style="left:12%;right:12%;bottom:2%;height:8%;display:grid;place-items:center" ${ready?'data-drop="neg:stamp"':''}>蓋章區</div></div><div class="g2-neg-scatter">${all.map(negPaper).join('')}</div><button class="g2-stamp ${g2.negStamped?'stamped':''}" data-item="neg:stamp" ${ready?'':'disabled'}>黨團協商<br>完成</button></div>`)}
const ORDER=['廣泛討論','逐條討論','條文議決'];
function orderPaper(x){return `<button class="g2-paper order" data-item="order:${x}"><b>${x}</b><small>第二讀會程序</small></button>`}
function second(){let source=(g2.orderPool||['條文議決','廣泛討論','逐條討論']).filter(x=>!g2.order.includes(x));let full=g2.order.filter(Boolean).length===3;g2Scene('chamber',`<p class="g2-prompt">把議事程序紙條依序放回紀錄板。</p><div class="g2-order-board"><b>第二讀會程序紀錄</b><div>${[0,1,2].map(i=>`<div class="g2-order-slot" data-drop="order:${i}"><i>${['①','②','③'][i]}</i>${g2.order[i]?orderPaper(g2.order[i]):''}</div>`).join('')}</div><button class="g2-confirm ${full?'ready':''}" data-action="confirm-order">確認程序</button></div><div class="g2-order-source">${source.map(orderPaper).join('')}</div>`)}
function third(){let page=g2.third;let firstPage=`<article class="g2-third-page"><em>第三讀會・修正便條</em><p>原文：「違反者處新臺幣 <mark>一萬元</mark> 罰鍰。」</p><p>修正：「違反者處新臺幣 <mark>十萬元</mark> 罰鍰。」</p><div><button class="g2-review-stamp" data-action="third" data-value="accept-big">接受修正</button><button class="g2-review-stamp" data-action="third" data-value="reject-big">退回</button></div></article>`;let secondPage=`<article class="g2-third-page"><em>第三讀會・修正便條</em><p>原文：「主管機關應予以通知。」</p><p>修正：「主管機關應通知。」</p><small>義務內容未改變，僅精簡文字。</small><div><button class="g2-review-stamp" data-action="third" data-value="accept-small">接受修正</button><button class="g2-review-stamp" data-action="third" data-value="reject-small">退回</button></div></article>`;g2Scene('chamber dark',`<div class="g2-desk-lamp"></div>${page===0?firstPage:page===1?secondPage:`<article class="g2-third-page passed"><div class="g2-big-stamp">文字修正</div><p>修正已確認，準備進行全案表決。</p><button class="g2-vote" data-action="third-vote">全案表決</button></article>`}`)}
function falsefinish(){g2Scene('chamber',`<article class="g2-false-finish"><div class="g2-big-stamp">三讀通過</div><p>議場裡響起主席槌聲，文件似乎終於完成了。</p><button data-action="false-finish">完成</button></article>`)}
function promulgation(){g2Scene('chamber',`<article class="g2-envelope" data-item="promulgation:envelope"><em>三讀通過法律案</em><b>立法院咨請公布</b></article><p class="g2-prompt">公文應送往哪一個機關？</p><div class="g2-recipients"><button class="g2-tray" data-drop="promulgation:executive">行政院</button><button class="g2-tray" data-drop="promulgation:president">總統府</button><button class="g2-tray" data-drop="promulgation:judicial">司法院</button></div>`)}
function effective(){g2Scene('chamber',`<article class="g2-public-record"><em>公布紀錄</em><b>公布日期：10月12日</b><small>本法規定自公布日施行。</small></article><div class="g2-calendar">${['10/12','10/13','10/14','10/15'].map((d,i)=>`<button data-drop="effective:${i}"><b>${d}</b></button>`).join('')}</div><button class="g2-effective-stamp" data-item="effective:stamp">生效</button>`)}
function verify(){let blanks=[['report','本案審查後，決議：'],['direct','逕付二讀後，接下來：'],['promulgation','三讀通過後，立法院咨請：']];let source=['report','direct','promulgation'].filter(id=>!g2.verify.includes(id));g2Scene('chamber',`<p class="g2-prompt">以文件夾中的證據，核對本案立法程序紀錄。</p><article class="g2-verify-sheet"><h2>本案立法程序紀錄</h2>${blanks.map(([id,label],i)=>`<button class="g2-verify-row" data-drop="verify:${i}"><span>${label}</span><b>${g2.verify[i]?G2_DOCS[g2.verify[i]].body.split('。')[0]:'＿＿＿＿＿＿＿＿'}</b></button>`).join('')}</article><div class="g2-evidence-source">${source.map(id=>g2Paper(id,'evidence')).join('')}</div>`)}
function complete(){g2Scene('chamber',`<article class="g2-complete"><div class="g2-big-stamp">程序完成</div><h2>尚未完成的法案</h2><p>提案 → 程序委員會 → 一讀 → 分流</p><p>委員會審查 → 視本案情況進入協商<br>逕付二讀 → 黨團協商<br>→ 二讀 → 三讀 → 總統公布 → 生效</p><button data-action="notebook">公民筆記02｜立法程序</button><button data-action="reset">重新測試第二關</button></article>`)}
function notebook(){let sections=(window.LEVEL2_CONTENT?.notebook?.sections)||[];g2Scene('chamber',`<article class="g2-notebook"><h1>公民筆記02｜立法程序</h1>${sections.map(([h,ps])=>`<section><h2>${h}</h2>${ps.map(p=>`<p>${p}</p>`).join('')}</section>`).join('')}<button data-action="reset">收起筆記，重新測試第二關</button></article>`)}
function g2Advance(stage,msg){g2.stage=stage;g2Save();g2Render();if(msg)g2Message(msg)}
function g2Act(item,drop){let [type,id]=item.split(':');let [zone,target]=drop.split(':');
 if(g2.stage==='agenda'&&type==='bill'){if(target!=='procedure')return g2Message(target==='committee'?'尚未經院會交付，不能直接進入委員會審查。':'程序尚未走到第二讀會。');if(!g2.agenda.includes(id))g2.agenda.push(id);if(g2.agenda.length===2){g2AddDoc('agenda');return g2Advance('first','議事日程審定。兩案已排入院會議程。')}g2Save();return g2Render()}
 if(g2.stage==='branch'&&type==='bill'){let ok=(id==='blue'&&target==='committee')||(id==='orange'&&target==='direct');if(!ok)return g2Message('這份議案的程序紀錄不是這樣。');g2.branch[id]=target;if(g2.branch.blue&&g2.branch.orange)return g2Advance('direct','兩案分流。先追蹤逕付二讀的紀錄。');g2Save();return g2Render()}
 if(g2.stage==='direct'&&type==='sign'&&target==='sign'){g2.sign=Math.min(20,g2.sign+1);g2Save();return g2Render()}
 if(g2.stage==='directexit'&&type==='bill'){if(target!=='negotiation')return g2Message('程序尚未完成。再看看逕付二讀紀錄。');g2AddDoc('direct');return g2Advance('committee','委員案已停在黨團協商桌等待。')}
 if(g2.stage==='committee'&&type==='review'&&target==='folder'){if(!g2.review.includes(id))g2.review.push(id);if(g2.review.length===3){g2AddDoc('report');return g2Advance('committeeexit','委員會審查報告已整理完成。')}g2Save();return g2Render()}
 if(g2.stage==='committeeexit'&&type==='bill'){if(target!=='negotiation')return g2Message('程序似乎還沒有完成。再看看審查報告。');return g2Advance('negotiation','兩案在黨團協商會合。')}
 if(g2.stage==='negotiation'&&type==='neg'){if(target==='stamp'){if(g2.negSlots.every(Boolean)){g2.negStamped=true;g2AddDoc('negotiation');return g2Advance('second','黨團協商完成。')}return}let slot=+target;if(id==='report')return g2Message('這是前一階段留下的審查文件。');if(id==='second')return g2Message('這份紀錄現在還不會出現。');let correct=['head','body','sign'][slot];if(id!==correct)return g2Message('文件的位置似乎不對。');g2.negSlots[slot]=id;g2Save();return g2Render()}
 if(g2.stage==='second'&&type==='order'){let slot=+target,old=g2.order[slot],from=g2.order.indexOf(id);if(from>-1)g2.order[from]=old||null;g2.order[slot]=id;g2Save();return g2Render()}
 if(g2.stage==='promulgation'&&type==='promulgation'){if(target!=='president')return g2Message('這不是公布法律的機關。');g2.promulgated=true;g2AddDoc('promulgation');return g2Advance('effective','立法院咨請總統公布。公布日期：10月12日。')}
 if(g2.stage==='effective'&&type==='effective'){if(target!=='2')return g2Message('日期似乎不對，再算一次。');g2.effective=true;return g2Advance('verify','法律生效。現在核對這份程序紀錄。')}
 if(g2.stage==='verify'&&type==='evidence'){let slot=+target,needed=['report','direct','promulgation'][slot];if(id!==needed)return g2Message('這份文件不是這個缺口的證據。');g2.verify[slot]=id;g2CheckDoc(id);if(g2.verify.every(Boolean)){g2.done=true;g2Save();return g2Advance('complete','程序紀錄核對完成。')}g2Save();return g2Render()}
}
function g2Action(a,el){if(a==='close'){document.querySelector('.g2-modal')?.remove();return g2Render()}if(a==='folder')return g2Folder();if(a==='doc')return g2ShowDoc(el.dataset.docid);if(a==='intro'){g2.intro=true;g2Save();return g2Render()}if(a==='viewbill')return g2ViewBill(el.dataset.bill);if(a==='to-agenda')return g2Advance('agenda');if(a==='first'){if(el.dataset.value!=='朗讀議案標題')return g2Message('尚未進入該程序。');return g2Advance('branch','一讀完成。兩案將走向不同的程序。')}if(a==='vote'){if(g2.sign<20)return;g2AddDoc('direct');return g2Advance('directexit','院會表決通過，橘案逕付二讀。')}if(a==='confirm-order'){let ok=g2.order.join('|')===ORDER.join('|');if(!ok){document.querySelector('.g2-order-board')?.classList.add('shake');g2Message('程序順序似乎不對，再檢查一次。');return setTimeout(()=>document.querySelector('.g2-order-board')?.classList.remove('shake'),450)}g2AddDoc('second');return g2Advance('third','二讀完成。')}if(a==='third'){let v=el.dataset.value;if(v==='accept-big')return g2Message('這不只是文字修正。');if(v==='reject-big'){g2.third=1;g2Save();return g2Render()}if(v==='accept-small'){g2.third=2;g2Save();return g2Render()}return g2Message('請再比對修正內容。')}if(a==='third-vote'){g2AddDoc('third');return g2Advance('falsefinish','三讀通過。')}if(a==='false-finish'){g2.falseFinish=true;g2Save();return g2Advance('promulgation','程序紀錄似乎還沒有完成。三讀通過，就代表法律已經生效了嗎？')}if(a==='notebook')return notebook();if(a==='reset'){g2=G2_INIT();g2Save();return g2Render()}}
function g2Bind(){document.querySelectorAll('[data-action]').forEach(e=>e.addEventListener('click',()=>g2Action(e.dataset.action,e)));document.querySelectorAll('[data-item]').forEach(e=>e.addEventListener('pointerdown',ev=>{g2.selected=e.dataset.item;document.querySelectorAll('[data-item]').forEach(x=>x.classList.toggle('picked',x===e));e.setPointerCapture?.(ev.pointerId);ev.preventDefault()}));document.querySelectorAll('[data-drop]').forEach(e=>e.addEventListener('pointerup',ev=>{if(g2.selected){let x=g2.selected;g2.selected=null;g2Act(x,e.dataset.drop);ev.preventDefault()}}));let pan=document.querySelector('#g2-explore-pan');if(pan){let down=false,startX=0,startLeft=0;pan.scrollLeft=(pan.scrollWidth-pan.clientWidth)/2;pan.addEventListener('pointerdown',ev=>{if(ev.target.closest('.g2-scene-file,.g2-begin-procedure,.g2-hud'))return;down=true;startX=ev.clientX;startLeft=pan.scrollLeft;pan.setPointerCapture?.(ev.pointerId);pan.classList.add('dragging')});pan.addEventListener('pointermove',ev=>{if(!down)return;pan.scrollLeft=startLeft-(ev.clientX-startX);ev.preventDefault()});['pointerup','pointercancel'].forEach(type=>pan.addEventListener(type,()=>{down=false;pan.classList.remove('dragging')}))}if(!window.__g2Pointer){window.__g2Pointer=true;document.addEventListener('pointerup',ev=>{if(!g2.selected)return;let zone=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-drop]');let x=g2.selected;g2.selected=null;if(zone)g2Act(x,zone.dataset.drop)})}}
g2App.style.maxWidth='none';g2App.style.width='100vw';g2App.style.margin='0';document.documentElement.style.setProperty('--g2-evidence-board',"url('assets/overlays/evidence-clipboard-v1.png')");
g2Start();
